  'duration': const .required(.integer),
  'totalVolume': const .required(.number),
  'muscles': .required(countMapShape),
  'patterns': .required(countMapShape),
  'unplacedSets': const .optional(.integer),
});

/// Open: `sets`, `primarySets` and `sessions` by the name being counted.
final Shape<Object?> countMapShape = .described(
  'CountMap',
  {},
  open: true,
);

final Shape<MeBalance> meBalanceShape = .model(
  'MeBalance',
  {
    'weekStart': const .required(.integer),
    'from': const .required(.isoString),
    'to': const .required(.isoString),
    'weeks': const .required(.integer),
    'pairs': .required(_override('MeBalance.pairs')),
    'warnings': .optional(.list(warningShape)),
  },
  description: '`GET /me/balance`: each pair\'s two sides set against each other over the window, counts only.',
);

final Shape<MeLibrarySearch> meLibrarySearchShape = .model(
  'MeLibrarySearch',
  {
    'exercises': .required(.list(meLibrarySearchExerciseShape)),
  },
  description:
      'Library search results: the exercises `SearchMatch` ranks best first, then by name, archived ones left out.',
);

final Shape<Object?> meLibrarySearchExerciseShape = .described('MeLibrarySearchExercise', {
  'id': const .required(
    .string,
    null,
    'The identity: the server row\'s uuid, or the client-minted UUIDv7 for a custom exercise created offline (the server persists that id on sync).',
  ),
  'name': const .required(
    .string,
    null,
    'Localized display copy for the locale the library was fetched under — never an identifier.',
  ),
  'category': .required(.enumOf<Category>(Category.values, (value) => value.value)),
  'target': .required(.enumOf<Target>(Target.values, (value) => value.value)),
  'aliases': .optional(.list(.string)),
  'own': const .optional(.boolean),
  'match': .required(.enumOf<SearchMatch>(SearchMatch.values, (value) => value.name)),
});

/// What `toWarnings()` writes.
final Shape<Iterable<Object?>> warningsShape = .list(warningShape);

Shape<Object?> _override(String key) => shapeOverrides[key]!.shape!;
